import{_ as r,o as a,c as o,ag as e}from"./chunks/framework.Aev9KvMf.js";const c=JSON.parse('{"title":"养老金身故后怎么办 · 继承与遗属待遇（家庭必读）","description":"家人去世后养老金怎么处理：个人账户余额依法继承、139 个月计发月数是什么、丧葬补助金与抚恤金、身故后该办的四件事。","frontmatter":{"title":"养老金身故后怎么办 · 继承与遗属待遇（家庭必读）","issuer":"依据《中华人民共和国社会保险法》及人力资源社会保障部文件整理","source_tier":"一级来源","version":"现行政策","published":2021,"source_url":"https://si.12333.gov.cn/","status":"现行","tags":["社保","养老金","继承","遗属待遇","城乡居民养老保险","家庭财务"],"type":"社保词条","reviewed":false,"description":"家人去世后养老金怎么处理：个人账户余额依法继承、139 个月计发月数是什么、丧葬补助金与抚恤金、身故后该办的四件事。"},"headers":[],"relativePath":"social/pension-after-death.md","filePath":"social/pension-after-death.md"}'),d={name:"social/pension-after-death.md"};function n(s,t,l,i,h,g){return a(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="养老金身故后怎么办-·-继承与遗属待遇-家庭必读" tabindex="-1">养老金身故后怎么办 · 继承与遗属待遇（家庭必读） <a class="header-anchor" href="#养老金身故后怎么办-·-继承与遗属待遇-家庭必读" aria-label="Permalink to &quot;养老金身故后怎么办 · 继承与遗属待遇（家庭必读）&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据《社会保险法》与人力资源社会保障部公开政策整理，<strong>具体数字（尤其抚恤金月数、地方丧葬补助标准）务必对照原文或拨打 12333 核实</strong>；各地执行细则不同，以当地社保经办机构为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家法律法规与部委文件</strong>，逐条标注出处；不构成法律或财务建议。这是一类&quot;不知道要吃亏、知道了能止损&quot;的家庭 tips 集合。</p></div><h2 id="速览卡-三句话记住" tabindex="-1">速览卡（三句话记住） <a class="header-anchor" href="#速览卡-三句话记住" aria-label="Permalink to &quot;速览卡（三句话记住）&quot;">​</a></h2><ol><li>参保人身故后，养老金<strong>从次月起停发</strong>——家属应及时申报，<strong>冒领须全额退还</strong>。</li><li><strong>养老保险个人账户的余额可以依法继承</strong>（《社会保险法》第十四条）——&quot;人没了钱充公&quot;是误解。</li><li>符合条件的遗属还能领<strong>丧葬补助金</strong>（职工养老全国有统一办法；城乡居民的丧葬补助金已普遍建立，<strong>标准各地不同</strong>）。</li></ol><h2 id="你听说过的-139-个月-精确说法是——" tabindex="-1">你听说过的&quot;139 个月&quot;，精确说法是—— <a class="header-anchor" href="#你听说过的-139-个月-精确说法是——" aria-label="Permalink to &quot;你听说过的&quot;139 个月&quot;，精确说法是——&quot;">​</a></h2><p>139 不是&quot;领钱年限&quot;，而是<strong>计发月数</strong>：60 岁开始领取时，个人账户养老金 = 个人账户储存额 ÷ 139，按月发放。对应关系（〔国发〔2005〕38 号〕附件，待核验）：</p><table tabindex="0"><thead><tr><th>开始领取年龄</th><th>计发月数</th></tr></thead><tbody><tr><td>50 岁</td><td>195 个月</td></tr><tr><td>55 岁</td><td>170 个月</td></tr><tr><td><strong>60 岁</strong></td><td><strong>139 个月</strong></td></tr></tbody></table><p>于是身故时只分两种情况：</p><table tabindex="0"><thead><tr><th>情况</th><th>个人账户部分</th></tr></thead><tbody><tr><td>领不满计发月数就身故</td><td><strong>没领完的余额由继承人依法继承</strong>（《社会保险法》第十四条）</td></tr><tr><td>领满计发月数后身故</td><td>个人账户部分已按月发完；遗属走丧葬补助金/抚恤金渠道</td></tr></tbody></table><p><strong>注意</strong>：月领养老金里的&quot;基础养老金&quot;（统筹/财政部分）只发到身故当月，不存在继承问题——能继承的只有<strong>个人账户</strong>余额。</p><h2 id="两条线分开看" tabindex="-1">两条线分开看 <a class="header-anchor" href="#两条线分开看" aria-label="Permalink to &quot;两条线分开看&quot;">​</a></h2><h3 id="城乡居民养老保险-农村居民、无业居民多在这条线" tabindex="-1">城乡居民养老保险（农村居民、无业居民多在这条线） <a class="header-anchor" href="#城乡居民养老保险-农村居民、无业居民多在这条线" aria-label="Permalink to &quot;城乡居民养老保险（农村居民、无业居民多在这条线）&quot;">​</a></h3><ul><li>个人账户余额：<strong>依法继承</strong>，凭死亡证明、继承人关系证明到社保经办机构办理（《社会保险法》第十四条）。</li><li>丧葬补助金：制度已普遍建立，<strong>标准由各省确定，各地不同</strong>（有的数百元、有的上千元）——问当地 12333。</li><li>基础养老金（政府发放部分）：发到身故当月为止。</li></ul><h3 id="城镇职工养老保险-在职-退休职工" tabindex="-1">城镇职工养老保险（在职/退休职工） <a class="header-anchor" href="#城镇职工养老保险-在职-退休职工" aria-label="Permalink to &quot;城镇职工养老保险（在职/退休职工）&quot;">​</a></h3><ul><li>个人账户余额：同样依法继承。</li><li>遗属待遇全国统一（《企业职工基本养老保险遗属待遇暂行办法》，人社部发〔2021〕56 号，<strong>待核验</strong>）： <ul><li><strong>丧葬补助金</strong> = 2 个月的本省上年度城镇居民月人均可支配收入；</li><li><strong>抚恤金</strong> = 按缴费年限确定发放月数（约 9～24 个月框架），退休人员每领取 1 年养老金递减 1 个月，<strong>最低 9 个月</strong>——具体月数以文件原文为准。</li></ul></li></ul><h3 id="住房公积金-另一笔容易被遗忘的钱" tabindex="-1">住房公积金（另一笔容易被遗忘的钱） <a class="header-anchor" href="#住房公积金-另一笔容易被遗忘的钱" aria-label="Permalink to &quot;住房公积金（另一笔容易被遗忘的钱）&quot;">​</a></h3><p>职工身故后，公积金账户余额由<strong>继承人申请提取</strong>（《住房公积金管理条例》，待核验）——凭死亡证明与继承关系证明到当地公积金中心办理，热线 <strong>12329</strong>。</p><h2 id="行动清单-现在就该做的" tabindex="-1">行动清单（现在就该做的） <a class="header-anchor" href="#行动清单-现在就该做的" aria-label="Permalink to &quot;行动清单（现在就该做的）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>怎么做</th><th>出处/工具</th></tr></thead><tbody><tr><td>给家中老人做<strong>待遇资格认证</strong>（每年一次，App 刷脸即可）——不认证会被<strong>停发</strong>，这是比继承常见得多的&quot;钱没了&quot;原因</td><td><a href="/SageRelay/query/si-12333.html">国家社会保险公共服务平台</a></td></tr><tr><td>查清参保类型与个人权益记录（缴费年限、账户余额）</td><td><a href="/SageRelay/query/si-12333.html">国家社会保险公共服务平台</a>、12333 热线</td></tr><tr><td>用官方&quot;养老金测算&quot;工具预估待遇</td><td><a href="/SageRelay/query/si-12333.html">国家社会保险公共服务平台</a></td></tr><tr><td>身故后家属四步：①及时申报停发 ②办丧葬补助金/抚恤金 ③继承个人账户余额 ④继承公积金</td><td>当地社保经办机构、12333、12329</td></tr><tr><td>【本站提示】把本页速览卡的三句话讲给父母/配偶听——这类信息最怕&quot;事到临头不知道&quot;</td><td>—</td></tr></tbody></table><h2 id="常见误区-逐条纠正" tabindex="-1">常见误区（逐条纠正） <a class="header-anchor" href="#常见误区-逐条纠正" aria-label="Permalink to &quot;常见误区（逐条纠正）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确说法</th><th>出处</th></tr></thead><tbody><tr><td>&quot;139 个月领完，账户就清零人财两空&quot;</td><td>139 只是<strong>除数</strong>；养老金（基础+个人账户）<strong>活多久领多久</strong>，与 139 无关</td><td>计发月数规则（待核验）</td></tr><tr><td>&quot;人不在了，交的钱充公&quot;</td><td><strong>个人账户余额依法继承</strong></td><td>《社会保险法》第十四条（<a href="http://www.gov.cn/flfg/2010-10/28/content_1732964.htm" target="_blank" rel="noreferrer">gov.cn 法律原文页</a>，自动化访问受限，请浏览器打开核验）</td></tr><tr><td>&quot;老人去世先瞒着，多领几个月不亏&quot;</td><td>冒领属违法行为，<strong>必须全额退还</strong>，还会影响遗属待遇办理——正确顺序是先申报后领遗属待遇</td><td>社保经办规则（待核验）</td></tr><tr><td>&quot;丧葬费全国一个标准&quot;</td><td>职工养老全国统一办法；<strong>城乡居民的标准各地不同</strong></td><td>人社部发〔2021〕56 号（待核验）、地方规定</td></tr></tbody></table><h2 id="相关工具" tabindex="-1">相关工具 <a class="header-anchor" href="#相关工具" aria-label="Permalink to &quot;相关工具&quot;">​</a></h2><ul><li><a href="/SageRelay/query/si-12333.html">国家社会保险公共服务平台查询</a> · <a href="/SageRelay/query/housing-fund.html">公积金查询</a> · <a href="/SageRelay/query/elder-care.html">养老地图</a></li><li>政策咨询：<strong>12333</strong>（社保）/ <strong>12329</strong>（公积金）</li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>法律</td><td>《中华人民共和国社会保险法》（2018 修正）第十四条等</td></tr><tr><td>部委文件</td><td>《企业职工基本养老保险遗属待遇暂行办法》（人社部发〔2021〕56 号，待核验）；国发〔2005〕38 号（计发月数，待核验）</td></tr><tr><td>行政法规</td><td>《住房公积金管理条例》（继承提取条款，待核验）</td></tr><tr><td>核验入口</td><td><a href="https://si.12333.gov.cn/" target="_blank" rel="noreferrer">国家社会保险公共服务平台</a>（已核验可达）· 12333 · 12329</td></tr></tbody></table>',26)])])}const b=r(d,[["render",n]]);export{c as __pageData,b as default};
